<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;
use Iterator;
use Throwable;
use Civi\Lughauth\Features\Document\Snippet\Application\Service\Visibility\SnippetVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\SnippetAssetRef;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\SnippetAssetAttributes;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\SnippetAsset;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetFilter;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetCursor;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetReadGateway;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetSlide;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SnippetAssetVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SnippetAssetReadGateway $readGateway,
        private readonly SnippetAssetWriteGateway $writeGateway,
        private readonly SnippetVisibilityService $snippetVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(SnippetAsset $content): SnippetAssetAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(SnippetAsset $content): SnippetAssetAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(SnippetAssetAttributes $attributes, ?SnippetAsset $original = null): SnippetAssetAttributes
    {
        $this->logDebug("Copy with fixed for Snippet asset");
        $span = $this->startSpan("Copy with fixed for  Snippet asset");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new SnippetAssetPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(SnippetAssetAttributes $attributes, ?SnippetAsset $original = null): SnippetAssetAttributes
    {
        $this->logDebug("Copy with hidden for Snippet asset");
        $span = $this->startSpan("Copy with hidden for  Snippet asset");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|SnippetAssetRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for Snippet asset");
        $span = $this->startSpan("Check visibility of an iterator for  Snippet asset");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new SnippetAssetRef($value));
            } elseif ($value instanceof SnippetAssetRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new SnippetAssetFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(SnippetAssetFilter $filter, ?SnippetAssetCursor $cursor = null): SnippetAssetSlide
    {
        $this->logDebug("List visibles for Snippet asset");
        $span = $this->startSpan("List visibles for  Snippet asset");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (SnippetAsset $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(SnippetAssetFilter $filter): int
    {
        $this->logDebug("Count visibles for Snippet asset");
        $span = $this->startSpan("Count visibles for  Snippet asset");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(SnippetAssetFilter $filter, ?SnippetAssetCursor $cursor = null): SnippetAssetSlide
    {
        $this->logDebug("List visibles for update for Snippet asset");
        $span = $this->startSpan("List visibles for update for  Snippet asset");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (SnippetAsset $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(SnippetAssetFilter $filter): int
    {
        $this->logDebug("Count visibles for update for Snippet asset");
        $span = $this->startSpan("Count visibles for update for  Snippet asset");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(SnippetAssetRef $ref): ?SnippetAsset
    {
        $this->logDebug("Retrieve visible for Snippet asset");
        $span = $this->startSpan("Retrieve visible for  Snippet asset");
        try {
            $filter = new SnippetAssetFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(SnippetAssetRef $ref): ?SnippetAsset
    {
        $this->logDebug("Retrieve visible for update for Snippet asset");
        $span = $this->startSpan("Retrieve visible for update for  Snippet asset");
        try {
            $filter = new SnippetAssetFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?SnippetAssetRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for Snippet asset");
        $span = $this->startSpan("Check fields for fix for Snippet asset");
        try {
            $result = $this->dispatcher->dispatch(new SnippetAssetCollectNonEditableFields(SnippetAsset::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?SnippetAssetRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for Snippet asset");
        $span = $this->startSpan("Check fields to hide for  Snippet asset");
        try {
            $result = $this->dispatcher->dispatch(new SnippetAssetCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(SnippetAssetAttributes $attributes): SnippetAssetAttributes
    {
        $this->logDebug("Check visibility of parent references for Snippet asset");
        $span = $this->startSpan("Check visibility of parent references for  Snippet asset");
        try {
            $snippet = $attributes->getSnippet();
            if (null !== $snippet && !$this->snippetVisibilityService->checkVisibility($snippet)) {
                throw new NotFoundException("Unknown Snippet " . ($snippet->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(SnippetAssetFilter $filter): SnippetAssetFilter
    {
        $this->logDebug("Compose visibility filter for Snippet asset");
        $span = $this->startSpan("Compose visibility filter for  Snippet asset");
        try {
            $result = $this->dispatcher->dispatch(new SnippetAssetRestrictFilterToVisibility($filter));
            return $result->snippetAssetFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(SnippetAsset $value): bool
    {
        $this->logDebug("Check if item is visible for Snippet asset");
        $span = $this->startSpan("Check if item is visible for  Snippet asset");
        try {
            $result = $this->dispatcher->dispatch(new SnippetAssetVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(SnippetAsset $content, bool $inlist): SnippetAssetAttributes
    {
        $this->logDebug("Prepare hydration to visible data for Snippet asset");
        $span = $this->startSpan("Prepare hydration to visible data for Snippet asset");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new SnippetAssetEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
